function validate([values, edges, maxTime]) {
  const n = values.length;
  if (n < 1 || n > 1000) return 'values needs 1 to 1000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 0 || v > 1e8)) return 'Each value is an integer between 0 and 10^8.';
  if (edges.length > 2000) return 'There are at most 2000 edges.';
  if (!Number.isInteger(maxTime) || maxTime < 10 || maxTime > 100) return 'maxTime is between 10 and 100.';
  const degree = new Array(n).fill(0);
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [u, v, time].';
    const [u, v, time] = edge;
    if (!Number.isInteger(u) || !Number.isInteger(v) || u < 0 || u >= v || v >= n) return 'Each edge needs 0 <= u < v <= n - 1.';
    if (!Number.isInteger(time) || time < 10 || time > 100) return 'Each edge time is between 10 and 100.';
    const key = u * n + v;
    if (seen.has(key)) return 'No pair of nodes may be joined twice.';
    seen.add(key);
    if (++degree[u] > 4 || ++degree[v] > 4) return 'Each node has at most four edges.';
  }
  return null;
}

