function maximalPathQuality(values, edges, maxTime) {
  const graph = values.map(() => []);
  for (const [u, v, time] of edges) {
    graph[u].push([v, time]);
    graph[v].push([u, time]);
  }
  const visits = new Array(values.length).fill(0);
  let best = 0;

  function dfs(node, elapsed, quality) {
    if (node === 0) {
      best = Math.max(best, quality);
    }
    for (const [next, time] of graph[node]) {
      if (elapsed + time > maxTime) {
        continue;
      }
      const gain = visits[next] === 0 ? values[next] : 0;
      visits[next]++;
      dfs(next, elapsed + time, quality + gain);
      visits[next]--;
    }
  }

  visits[0] = 1;
  dfs(0, 0, values[0]);
  return best;
}

