function maximalPathQuality(values, edges, maxTime) {
  // Enumerate every walk from node 0 with an explicit stack, scoring walks that end at 0 by their set of nodes.
  let best = values[0];
  const stack = [[[0], 0]];
  while (stack.length > 0) {
    const [path, spent] = stack.pop();
    const last = path[path.length - 1];
    if (last === 0) {
      let total = 0;
      for (const node of new Set(path)) total += values[node];
      best = Math.max(best, total);
    }
    for (const [u, v, t] of edges) {
      if (spent + t > maxTime) continue;
      if (u === last) stack.push([[...path, v], spent + t]);
      else if (v === last) stack.push([[...path, u], spent + t]);
    }
  }
  return best;
}

