function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? 1000 : int(1, 6);
  const values = Array.from({ length: n }, () => large || rand() < 0.15 ? int(0, 1e8) : int(0, 50));
  const degree = new Array(n).fill(0);
  const seen = new Set();
  const edges = [];
  const target = n < 2 ? 0 : large ? int(1500, 2000) : int(0, Math.min(10, (n * (n - 1)) / 2));
  // Small graphs keep walks short (at most 6 edges) so the brute force stays fast.
  const maxTime = large ? int(60, 100) : int(10, 60);
  const edgeTime = () => large ? (rand() < 0.6 ? int(10, 20) : int(10, 100)) : int(10, 40);
  for (let tries = 0; edges.length < target && tries < 20 * target + 50; tries++) {
    // Large graphs pick most edges near node 0 so the search from 0 has plenty to explore.
    const spread = large && rand() < 0.5 ? 60 : n;
    let u = int(0, spread - 1);
    let v = int(0, spread - 1);
    if (u === v) continue;
    if (u > v) [u, v] = [v, u];
    const key = u * n + v;
    if (seen.has(key) || degree[u] >= 4 || degree[v] >= 4) continue;
    seen.add(key);
    degree[u]++;
    degree[v]++;
    edges.push([u, v, edgeTime()]);
  }
  return [values, edges, maxTime];
}
